<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Super Admin','College Admin','IT/System Administrator');check_csrf();$targets=['assignments'];if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['restore_e'],$_POST['restore_id'])){try{CrudService::restore($_POST['restore_e'],(int)$_POST['restore_id']);$_SESSION['flash']=['success','Record restored'];}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('recycle_bin.php');}page_top('Recycle Bin');flash();foreach($targets as $e){$m=entity_map()[$e]??null;if(!$m)continue;$q=db()->query("SELECT id,title,deleted_at,deleted_by FROM `{$m['table']}` WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC LIMIT 100");?><div class='card p-3 mb-4'><h5><?=e($m['label'])?></h5><div class='table-responsive'><table class='table'><tr><th>ID</th><th>Title</th><th>Deleted At</th><th>Action</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['id'])?></td><td><?=e($r['title'])?></td><td><?=e($r['deleted_at'])?></td><td><form method='post'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='restore_e' value='<?=e($e)?>'><input type='hidden' name='restore_id' value='<?=e($r['id'])?>'><button class='btn btn-sm btn-success'>Restore</button></form></td></tr><?php endforeach;?></table></div></div><?php } page_bottom(); ?>